/* midihandler code, compiled for size (only runs on MIDI / at start / LED rate) */
__attribute__((noinline,optimize("Os"))) void midiOs(midi_device_t dev,uint8_t port,uint8_t status,uint8_t data1,uint8_t data2){

uint8_t st=status&0xF0;
if(st==MIDI_CONTROL_CHANGE){
 if(data1==99){m99=data2;h99=true;h98=h6=false;}                      // patch cables (same parsing as PatchBay)
 else if(data1==98){m98=data2;h98=true;}
 else if(data1==6){m6=data2;h6=true;}
 if((data1==99||data1==98||data1==6)&&h99&&h98&&h6){h99=h98=h6=false;cable(m99,m98,m6);}
 for(int p=0;p<NP;p++){
  if(kcc[p]!=data1)continue;
  if(kind[p]==2){lastcc[p]=data2;break;}                                // rotary switch: MS20_Voices applies it, remembered for "panel"
  if(!lock[p]){setp(p,ccraw(kind[p],data2));lastcc[p]=data2;break;}
  // after a recall: scaling pickup - the value moves from where it is, in the knob's direction, scaled so that
  // value and knob reach the end of the range together; once they meet the knob is direct again
  if(lastcc[p]<0){lastcc[p]=data2;break;}                              // knob position not known yet: learn it, no change
  int d=data2-lastcc[p];
  if(d<2&&d>-2)break;                                                   // jitter filter: ignore 1-step wobble
  int64_t lo=(kind[p]==1)?-134217728:0,hi=0x07FFFFFF,v=cur[p];
  if(d>0)v+=(hi-v)*d/(127-lastcc[p]);else v-=(v-lo)*(-d)/lastcc[p];
  cur[p]=(int32_t)v;setp(p,cur[p]);lastcc[p]=data2;
  int g=rawcc(kind[p],cur[p])-data2;if(g<=1&&g>=-1)lock[p]=false;      // met: direct from now on
  break;
 }
}else if(st==0xD0){                                                     // momentary switch
 bool nb=(data1>0);
 if(nb&&!btn)tpress=tk;
 btn=nb;armed=btn&&!tapmode;            // immediate: the very next key press is already a memory key
}else if(st==MIDI_NOTE_ON&&data2>0){
 if(armed&&keyn<0&&data1>=BASE&&data1<=BASE+NS){keyn=data1;kdown=tk;saved=false;}
}else if(st==MIDI_NOTE_OFF||(st==MIDI_NOTE_ON&&data2==0)){
 if(data1==keyn){if(!saved)recall(keyn-BASE);keyn=-1;}                 // short press: recall on release
}

}

